## The Fix

Right, here's the corrected code. I've grown up a bit - now I think about the whole team, not just my own glory:

```go
package cache

import (
    "context"
    "sync"
    "sync/atomic"
    "time"
)

type CacheEntry struct {
    Value     interface{}
    ExpiresAt time.Time
    ready     chan struct{} // Signals when loading is complete
    err       error         // Store loading error
}

type LoadFunc func(ctx context.Context, key string) (interface{}, error)

type Cache struct {
    data   map[string]*CacheEntry
    mu     sync.RWMutex  // RWMutex for better read concurrency
    ttl    time.Duration
    loader LoadFunc
    stats  *Stats
}

type Stats struct {
    Hits       int64
    Misses     int64
    LoadErrors int64
}

func NewCache(ttl time.Duration, loader LoadFunc) *Cache {
    c := &Cache{
        data:   make(map[string]*CacheEntry),
        ttl:    ttl,
        loader: loader,
        stats:  &Stats{},
    }
    go c.cleanupLoop()
    return c
}

func (c *Cache) Get(ctx context.Context, key string) (interface{}, error) {
    // Fast path with read lock
    c.mu.RLock()
    entry, ok := c.data[key]
    c.mu.RUnlock()

    if ok {
        // Wait for loading to complete if needed
        select {
        case <-entry.ready:
        case <-ctx.Done():
            return nil, ctx.Err()
        }

        if entry.err != nil {
            return nil, entry.err
        }

        if time.Now().Before(entry.ExpiresAt) {
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        }
    }

    // Need to load - acquire write lock
    c.mu.Lock()

    // Double-check after acquiring lock
    if entry, ok := c.data[key]; ok {
        c.mu.Unlock()
        select {
        case <-entry.ready:
        case <-ctx.Done():
            return nil, ctx.Err()
        }
        if entry.err != nil {
            return nil, entry.err
        }
        if time.Now().Before(entry.ExpiresAt) {
            atomic.AddInt64(&c.stats.Hits, 1)
            return entry.Value, nil
        }
        // Entry expired, fall through to reload
        c.mu.Lock()
    }

    // Create loading entry with channel
    entry = &CacheEntry{ready: make(chan struct{})}
    c.data[key] = entry
    c.mu.Unlock()

    atomic.AddInt64(&c.stats.Misses, 1)

    // Load outside lock
    value, err := c.loader(ctx, key)

    c.mu.Lock()
    if err != nil {
        atomic.AddInt64(&c.stats.LoadErrors, 1)
        entry.err = err
    } else {
        entry.Value = value
        entry.ExpiresAt = time.Now().Add(c.ttl)
    }
    close(entry.ready) // Signal waiters
    c.mu.Unlock()

    if err != nil {
        return nil, err
    }
    return value, nil
}

func (c *Cache) Set(key string, value interface{}) {
    c.mu.Lock()
    defer c.mu.Unlock()
    entry := &CacheEntry{
        Value:     value,
        ExpiresAt: time.Now().Add(c.ttl),
        ready:     make(chan struct{}),
    }
    close(entry.ready)
    c.data[key] = entry
}

func (c *Cache) GetMulti(ctx context.Context, keys []string) map[string]interface{} {
    var wg sync.WaitGroup
    var mu sync.Mutex
    results := make(map[string]interface{})

    for _, key := range keys {
        wg.Add(1)
        go func(k string) {
            defer wg.Done()
            value, err := c.Get(ctx, k)
            if err == nil {
                mu.Lock()
                results[k] = value
                mu.Unlock()
            }
        }(key)
    }

    wg.Wait() // Proper synchronization!
    return results
}

func (c *Cache) cleanup() {
    c.mu.Lock()
    defer c.mu.Unlock()

    now := time.Now()
    for key, entry := range c.data {
        select {
        case <-entry.ready:
            if now.After(entry.ExpiresAt) {
                delete(c.data, key)
            }
        default:
            // Still loading, don't touch
        }
    }
}

func (c *Cache) Size() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return len(c.data)
}

func (c *Cache) GetStats() Stats {
    return Stats{
        Hits:       atomic.LoadInt64(&c.stats.Hits),
        Misses:     atomic.LoadInt64(&c.stats.Misses),
        LoadErrors: atomic.LoadInt64(&c.stats.LoadErrors),
    }
}
```

---

## Key Fixes Summary

| Race | Fix |
|------|-----|
| Unprotected map reads | Use `RWMutex`, always hold lock for map access |
| Stats counters | `atomic.AddInt64` and `atomic.LoadInt64` |
| cleaning flag | Removed - just use the mutex |
| GetMulti results | Added `sync.WaitGroup` + local mutex |
| waitForLoad | Replaced busy-wait with channel signaling |
| Cache stampede | Channel-based coordination, error propagation |

